export interface TimelineEvent {
  year: number;
  event: string;
  era: number;
  detailKey?: string;
}

export const TIMELINE_EVENTS: TimelineEvent[] = [
  { year: 850, event: "Chronology threshold — the detailed public timeline begins at 850 CE for navigational scope. This is not an origin date, first-presence claim, or limit on Indigenous histories. Nation-specific oral knowledge traditions and archaeological research belong to distinct evidence categories. Source: Oneida Indian Nation; National Park Service", era: 1, detailKey: "850_chronology_threshold" },
  { year: 850, event: "Ancestral Puebloans (Anasazi) reach their peak at Chaco Canyon, New Mexico — a sophisticated urban center with monumental great houses, a complex road system spanning hundreds of miles, and astronomical alignments. This civilization thrived for 400 years before European contact", era: 1 },
  { year: 1000, event: "Etowah Mounds (Cartersville, Georgia) occupied at peak — a Mississippian city of approximately 4,000 people with six earthen mounds, the largest standing 63 feet tall. Trade networks connect Georgia to the Great Lakes, Gulf Coast, and Appalachian Mountains", era: 1 },
  { year: 1050, event: "Cahokia (near present-day St. Louis) reaches peak population of 20,000–40,000 people — the largest pre-Columbian settlement north of Mexico. Its central mound, Monks Mound, is larger at its base than the Great Pyramid of Giza. Trade networks span the entire North American continent", era: 1 },
  { year: 1200, event: "The Haudenosaunee (Iroquois) Confederacy is founded by the Peacemaker and Hiawatha — uniting the Mohawk, Oneida, Onondaga, Cayuga, and Seneca nations under the Great Law of Peace. This participatory democracy, with its principles of federalism and checks and balances, will later influence the framers of the U.S. Constitution", era: 1 },
  { year: 1400, event: "The Aztec/Mexica Empire's capital Tenochtitlan (present-day Mexico City) reaches a population of 400,000 — larger than any city in Europe at the time. The Maya civilization has already built thousands of cities across Mesoamerica. The Americas are home to an estimated 60–100 million people", era: 1 },
  { year: 1452, event: "Papal Bull Dum Diversas authorizes Portuguese enslavement of non-Christians — the legal foundation of the Doctrine of Discovery", era: 1 },
  { year: 1492, event: "The Columbian Exchange begins — European contact introduces smallpox, measles, typhus, and influenza to the Americas. Indigenous populations, with no prior exposure, suffer catastrophic mortality. Historians estimate 56 million Indigenous people — approximately 90% of the pre-contact population — die within 150 years of first contact. The land Europeans called 'empty' or 'wilderness' had been depopulated by biological catastrophe. Source: Koch et al., Quaternary Science Reviews (2019)", era: 1 },
  { year: 1492, event: "Columbus's first voyage: makes landfall October 12 on Guanahani (Bahamas); his own journal records 'with fifty men they can all be subjugated' — the Doctrine of Discovery in plain language", era: 1 },
  { year: 1493, event: "Columbus's second voyage: 17 ships, 1,500 men; establishes the encomienda forced labor system; initiates the first transatlantic slave trade by shipping enslaved Taíno people to Spain", era: 1 },
  { year: 1494, event: "Treaty of Tordesillas divides the 'New World' between Spain and Portugal — the first international treaty built entirely on the Doctrine of Discovery, partitioning Indigenous lands without consent", era: 1 },
  { year: 1503, event: "Spain legally defines the encomienda system — granting conquistadors the right to demand labor and tribute from Indigenous people in exchange for 'protection.' The Taíno population of Hispaniola collapses from an estimated 300,000 to fewer than 300 within decades", era: 1 },
  { year: 1517, event: "First enslaved Africans shipped directly from Africa to the Americas — arriving in the Caribbean to replace the decimated Indigenous labor force. The transatlantic slave trade formally begins", era: 1 },
  { year: 1521, event: "Hernán Cortés conquers the Aztec Empire (Tenochtitlan). The Doctrine of Discovery is applied to the most populous civilization in the Americas — a city larger than any in Europe at the time", era: 1 },
  { year: 1526, event: "Spain passes the New Laws of the Indies — theoretically prohibiting Indigenous slavery while maintaining the encomienda system. The first documented attempt by enslaved Africans to escape in what is now the United States occurs in present-day South Carolina", era: 1 },
  { year: 1540, event: "De Soto’s expedition moves through the Coosa chiefdom; institutional histories document the expedition’s coercive taking of the Coosa leader as a hostage for passage. This is a record of colonial violence in a specific Indigenous polity, not a racial classification. Source: National Park Service", era: 1, detailKey: "1540_de_soto_coosa" },
  { year: 1542, event: "Bartolomé de Las Casas publishes 'A Short Account of the Destruction of the Indies' — the first eyewitness documentation of colonial genocide, estimating 12-15 million Indigenous deaths in 50 years of Spanish rule", era: 1 },
  { year: 1565, event: "Spain establishes St. Augustine, Florida — the first permanent European settlement in what becomes the United States, built on Timucua and Apalachee Indigenous territory", era: 1 },
  { year: 1606, event: "Virginia Company Charter granted by King James I — the first corporate colonialism template in North America. A joint-stock company of private investors is given the right to colonize Virginia for profit. This corporate structure — private investment, royal charter, Indigenous land seizure — is the direct template for the Georgia Charter (1732) and every subsequent colonial land grant", era: 1 },
  { year: 1607, event: "Jamestown, Virginia established — the first permanent English settlement in North America, built on Powhatan Confederacy territory. Within 3 years, English colonists are already enslaving Indigenous people", era: 1 },
  { year: 1614, event: "Tisquantum (Squanto), a Patuxet man, is abducted by Thomas Hunt and carried across the Atlantic — a documented episode of Indigenous captivity in the English Atlantic world. Later English accounts describe his sale in Málaga, passage to England, and eventual return to New England. Source: William Bradford, Of Plymouth Plantation; National Museum of the American Indian", era: 1, detailKey: "1614_tisquantum" },
  { year: 1619, event: "The Transatlantic Slave Trade: Between 1619 and 1808, an estimated 12.5 million people were forcibly transported from Africa to the Americas. Approximately 1.8 million — nearly 15% — died during the Middle Passage. The Trans-Atlantic Slave Trade Database documents 36,000 individual voyages. This is the largest forced migration in human history. Source: Slave Voyages Database, Emory University (slavevoyages.org)", era: 1 },
  { year: 1619, event: "Virginia House of Burgesses convenes — the first representative assembly in America. In the same year, the first enslaved Africans arrive in Virginia. Democracy for some, slavery for others, in the same year: this juxtaposition is the foundation of the American contradiction", era: 1 },
  { year: 1621, event: "Plymouth–Pokanoket agreement — Ousamequin (Massasoit) and Plymouth leaders make a mutual-defense and peace agreement recorded in English sources. The agreement shows Indigenous diplomacy as active political strategy amid epidemic, English settlement, and regional power shifts. Source: Mourt's Relation; William Bradford, Of Plymouth Plantation; Plimoth Patuxet Museums", era: 1, detailKey: "1621_plymouth_pokanoket" },
  { year: 1640, event: "Virginia passes the first laws specifically distinguishing enslaved Africans from white indentured servants — the legal beginning of race-based slavery in the English colonies. John Punch, a Black man, is sentenced to lifetime servitude while his two white companions receive extended indentures for the same offense", era: 1 },
  { year: 1676, event: "Bacon's Rebellion — poor white and Black indentured servants unite in armed rebellion against Virginia's planter elite. After the rebellion is crushed, Virginia planters deliberately create racial solidarity among poor whites through legislation, granting them privileges denied to Black people. This is the documented origin of race as a political tool to prevent cross-racial class alliances", era: 1 },
  { year: 1676, event: "King Philip’s War-era Indigenous captivity and overseas forced movement — colonial record routes and historical research document Native captives, including Wampanoag people, sent to overseas destinations. A 1677 record identifies New England Indians held at the Bagnio in Tangier; the claimed letters from captives to John Eliot are not verified. Source: Native Northeast Portal; Linford D. Fisher", era: 1, detailKey: "1676_wampanoag_deportation" },
  { year: 1683, event: "Eastern Pequot reservation context — Nation and Connecticut records identify the North Stonington reservation as established in 1683. The community’s controlling federal-acknowledgment determination was a 2005 denial, not the earlier 2002 positive determination. Source: Eastern Pequot Tribal Nation; BIA; Federal Register", era: 1, detailKey: "1683_eastern_pequot" },
  { year: 1705, event: "Virginia Slave Code — the comprehensive codification of American chattel slavery. Enslaved people are legally defined as property, not persons. All rights are stripped. The code explicitly states that 'all negro, mulatto, and Indian slaves' are 'real estate.' Every Southern slave code that follows is modeled on this document", era: 1 },
  { year: 1732, event: "Georgia Charter describes Indigenous lands as 'waste and desolate'", era: 1 },
  { year: 1739, event: "Stono Rebellion — the largest slave revolt in colonial British America. Approximately 60 enslaved people in South Carolina march toward Spanish Florida (which offered freedom), killing 25 white colonists. The direct response is the Negro Act of 1740, which prohibits enslaved people from moving freely, assembling, growing their own food, earning money, or learning to read. Georgia adopts the same restrictions", era: 1 },
  { year: 1776, event: "Declaration of Independence — freedom declared, slavery maintained", era: 1 },
  { year: 1785, event: "Treaty of Hopewell (Peace and Friendship) with Cherokee Nation — the first treaty between the U.S. and the Cherokee. The U.S. promises peace, protection, and permanent boundaries. Promise made: 'The hatchet shall be forever buried.' The U.S. violates it within years by failing to prevent illegal white settlements on Cherokee lands. Source: Kappler's Indian Affairs Laws and Treaties", era: 1 },
  { year: 1786, event: "Treaty of Hopewell with Choctaw and Chickasaw Nations — the U.S. promises peace, friendship, and protection. Both nations acknowledge U.S. sovereignty. Both treaties are violated within decades as the U.S. fails to prevent encroachment and begins pressuring for removal. Source: Kappler's Indian Affairs Laws and Treaties", era: 1 },
  { year: 1790, event: "Treaty of New York with Creek/Muscogee Nation — the first treaty under the new U.S. Constitution. The Creek Nation cedes lands to the Oconee River and agrees to return fugitive slaves. The U.S. promises to guarantee Creek territory and provide annual payments. The U.S. immediately fails to police the borders, allowing white settlers to infiltrate. Source: U.S. Statutes at Large, 7 Stat. 35", era: 1 },
  { year: 1791, event: "Haitian Revolution begins — terrifies American slaveholders", era: 1 },
  { year: 1791, event: "Treaty of Holston with Cherokee Nation — the U.S. promises permanent boundaries and protection from settlers. The Cherokee cede significant hunting grounds. The U.S. repeatedly violates the guaranteed boundaries within years, leading to further forced cessions and eventual removal. Source: Avalon Project, Yale Law School", era: 1 },
  { year: 1795, event: "Treaty of Greenville — 12 Northwest Territory nations cede vast lands in Ohio, Indiana, Illinois, and Michigan. The U.S. promises perpetual peace and annual goods worth $9,500. The U.S. continues pressuring for land cessions immediately after signing. Source: Yale Law School", era: 1 },
  { year: 1802, event: "Treaty of Fort Wilkinson — Creek Nation cedes Georgia lands along the Oconee, Ocmulgee, and Altamaha rivers. The U.S. promises $3,000 annually. The treaty is the first in a series of forced Creek cessions that will ultimately remove the entire nation from Georgia. Source: Kappler's Indian Affairs Laws and Treaties", era: 1 },
  { year: 1803, event: "Louisiana Purchase transfers 828,000 sq miles of Indigenous territory", era: 1 },
  { year: 1805, event: "Treaty of Washington with Cherokee Nation — Cherokee cede parts of Tennessee and Georgia for roads and settlements. The U.S. promises payments and agricultural assistance. The U.S. fails to protect Cherokee lands from encroachment and pressures for further cessions within years. Source: Kappler's Indian Affairs Laws and Treaties", era: 1 },
  { year: 1814, event: "Treaty of Fort Jackson — after the Battle of Horseshoe Bend, Andrew Jackson forces the Creek Nation to cede 23 million acres in Georgia and Alabama. Jackson imposes this on both hostile AND friendly Creek factions — including those who fought alongside him. The U.S. promises to guarantee remaining Creek territory. The promise is broken within a decade. Source: Kappler's Indian Affairs Laws and Treaties", era: 2 },
  { year: 1820, event: "Missouri Compromise — Congress draws a geographic line at 36°30' latitude: slavery permitted south of it, prohibited north of it. The first federal acknowledgment that slavery is a permanent feature of American life that must be managed, not abolished", era: 2 },
  { year: 1821, event: "Treaty of Indian Springs (first) — Creek Nation cedes 4.3 million acres in Georgia east of the Flint River. The U.S. promises $200,000 over 14 years. The treaty is later deemed fraudulent because Chief William McIntosh received personal land grants and payments for his role in the negotiations. Source: Kappler's Indian Affairs Laws and Treaties", era: 2 },
  { year: 1821, event: "Sequoyah completes the Cherokee syllabary", era: 2 },
  { year: 1825, event: "Treaty of Indian Springs (second) — William McIntosh signs away all remaining Creek lands in Georgia without tribal authorization. The Creek National Council condemns it as fraudulent. McIntosh is executed by his own people for the betrayal. The U.S. Senate ratifies it anyway. Source: Kappler's Indian Affairs Laws and Treaties", era: 2 },
  { year: 1826, event: "Treaty of Washington — Creek Nation forced to cede all remaining Georgia lands east of the Chattahoochee River. The U.S. promises $217,600 and a perpetual annuity of $20,000. The U.S. immediately continues its removal policy, rendering all guarantees meaningless. Source: Kappler's Indian Affairs Laws and Treaties", era: 2 },
  { year: 1828, event: "Cherokee Phoenix newspaper launched", era: 2 },
  { year: 1830, event: "Treaty of Dancing Rabbit Creek — the first removal treaty under the Indian Removal Act. The Choctaw Nation cedes 11 million acres of Mississippi homeland. The U.S. promises land west of the Mississippi and citizenship with land for those who remain. The U.S. fails to protect Choctaws who stay, subjecting them to harassment and legal conflict. Source: Kappler's Indian Affairs Laws and Treaties, 7 Stat. 333", era: 2 },
  { year: 1830, event: "Indian Removal Act signed by Andrew Jackson", era: 2 },
  { year: 1832, event: "Treaty of Pontotoc Creek and Treaty of Payne's Landing — Chickasaw Nation cedes 6 million acres of Mississippi lands; Seminole Nation relinquishes all Florida lands. Both treaties are signed under duress. The Seminole rejection of the Payne's Landing treaty leads directly to the Second Seminole War (1835–1842), the most expensive Indian war in U.S. history. Source: Kappler's Indian Affairs Laws and Treaties", era: 2 },
  { year: 1832, event: "Worcester v. Georgia — Marshall rules for Cherokee; Jackson ignores ruling", era: 2 },
  { year: 1835, event: "Treaty of New Echota — a minority faction of the Cherokee Nation (the Treaty Party) signs away 7 million acres of ancestral land without authorization from Principal Chief John Ross or the Cherokee National Council. 16,000 Cherokee sign a petition rejecting it. The U.S. Senate ratifies it by a single vote. The result is the Trail of Tears. Source: Kappler's Indian Affairs Laws and Treaties", era: 2 },
  { year: 1838, event: "Trail of Tears — 4,000+ Cherokee die on forced march", era: 2 },
  { year: 1845, event: "Southern Baptist Convention founded to defend slaveholders", era: 2 },
  { year: 1850, event: "Fugitive Slave Act — requires Northern states to return escaped enslaved people to their owners. Federal marshals can be fined $1,000 for refusing. Alleged fugitives are denied jury trials. The federal government forces every free state to become an active participant in slavery", era: 2 },
  { year: 1851, event: "Fort Laramie Treaty (first) — Cheyenne, Sioux, Arapaho, Crow, and other Plains nations recognize territorial boundaries and grant safe passage on the Oregon Trail. The U.S. promises $50,000 annually for 50 years. The U.S. immediately fails to enforce the treaty, allowing settlers to encroach during the Pike's Peak Gold Rush. Source: Kappler's Indian Affairs Laws and Treaties", era: 2 },
  { year: 1857, event: "Dred Scott v. Sandford — the Supreme Court rules that Black people have 'no rights which the white man was bound to respect.' Congress cannot prohibit slavery in any territory. The Missouri Compromise is void. Chief Justice Taney's ruling is the most devastating Supreme Court decision in American history before Plessy v. Ferguson", era: 2 },
  { year: 1863, event: "Emancipation Proclamation — President Lincoln declares enslaved people in Confederate states to be free. Its scope is deliberately limited: it does not apply to loyal border states or Union-occupied Confederate territories. It is a war measure, not a moral declaration. 4 million enslaved people remain legally in bondage", era: 2 },
  { year: 1865, event: "13th Amendment — abolishes slavery 'except as punishment for crime'", era: 2 },
  { year: 1865, event: "Georgia Black Codes immediately re-enslave Black labor", era: 2 },
  { year: 1865, event: "Mississippi and South Carolina Black Codes — selected state statutes regulate labor, movement, licensing, vagrancy, arms, and other aspects of civil life for people classified as freedmen, free Negroes, mulattoes, or persons of color. The texts establish state legal mechanisms, not uniform local outcomes. Source: state acts of 1865", era: 2, detailKey: "1865_black_codes" },
  { year: 1865, event: "South Carolina Black Code local-administration provisions — the statute assigns District Judges and Magistrates powers over specified labor-task complaints, alleged contract misconduct, fines or corporal punishment, and orders remanding servants to work. The text identifies a local enforcement mechanism; it does not by itself document a named official’s action in a particular case. Source: Acts of the General Assembly of South Carolina (1864–65), §§ XLVII, LII–LIII", era: 2, detailKey: "1865_sc_black_code_local_enforcement" },
  { year: 1865, event: "Circular No. 15 establishes a land-restoration policy — the Freedmen’s Bureau permits restoration of abandoned land to pardoned owners under stated procedures while protecting crops or requiring compensation for loyal freedpeople cultivating the land. Source: Circular No. 15 (September 12, 1865)", era: 2, detailKey: "1865_land_restoration" },
  { year: 1865, event: "Louisiana Freedmen’s Bureau land applications — a Record Group 105 register records names, household information, acreage requests, locations, and stated means for people applying to lease abandoned or confiscated land. Source: National Archives Identifier 595044", era: 2, detailKey: "1865_land_applications" },
  { year: 1866, event: "Freedmen’s Bureau Act extension — Congress continues and amends the Bureau’s authority over President Andrew Johnson’s veto. Source: 14 Stat. 173–77; U.S. Government Publishing Office", era: 2, detailKey: "1866_freedmens_bureau_act" },
  { year: 1866, event: "Civil Rights Act of 1866 — Congress overrides President Andrew Johnson’s veto and enacts the first federal civil-rights statute, declaring most U.S.-born persons citizens and securing the full and equal benefit of laws protecting person and property. The citizenship rule expressly excludes American Indians. Source: 14 Stat. 27; U.S. House Office of the Historian", era: 2, detailKey: "1866_civil_rights_act" },
  { year: 1867, event: "Medicine Lodge Treaty — Southern Plains nations (Cheyenne, Arapaho, Kiowa, Comanche, Plains Apache) are confined to reservations in Indian Territory. The U.S. promises food, clothing, and protection. The U.S. fails to provide promised provisions, and the Army continues attacking reservation communities. Source: Kappler's Indian Affairs Laws and Treaties", era: 2 },
  { year: 1868, event: "Fourteenth Amendment ratified — constitutionalizes citizenship, due process, equal protection, and Congress’s power to enforce those protections. The amendment becomes a foundation for later civil-rights claims, yet its promise remains subject to enforcement and judicial interpretation. Source: National Archives, Record Group 11", era: 2, detailKey: "1868_fourteenth_amendment" },
  { year: 1868, event: "Fort Laramie Treaty (second) — the Lakota Nation is guaranteed the Black Hills 'as long as the grass shall grow and the water flow.' The U.S. promises to protect the Great Sioux Reservation from all intrusion. In 1874, Custer's expedition discovers gold in the Black Hills. The U.S. violates the treaty and seizes the land. The Black Hills have never been returned. Source: National Archives, Treaty of Fort Laramie (1868)", era: 2 },
  { year: 1870, event: "Fifteenth Amendment ratified — the United States and states may not deny or abridge the right to vote on account of race, color, or previous condition of servitude. Source: National Archives, Record Group 11", era: 2, detailKey: "1870_fifteenth_amendment" },
  { year: 1870, event: "First Enforcement Act — Congress prohibits race-based discrimination in voter registration, creates federal penalties for interference with voting, and gives federal courts enforcement power. Source: 16 Stat. 140; U.S. House Office of the Historian", era: 2, detailKey: "1870_enforcement_act" },
  { year: 1871, event: "Third Enforcement Act (Ku Klux Klan Act) — Congress authorizes stronger federal action against conspiracies denying constitutional rights, including presidential use of military force and suspension of habeas corpus in specified circumstances. Source: 17 Stat. 13; U.S. House Office of the Historian", era: 2, detailKey: "1871_kkk_act" },
  { year: 1871, event: "Indian Appropriations Act — Congress ends future treaty-making with Indian nations while expressly preserving obligations of treaties lawfully made and ratified before March 3, 1871. The change redirected later federal dealings to legislation, executive action, and other legal instruments; it did not invalidate prior treaties. Source: 16 Stat. 566; National Archives; U.S. House, 25 U.S.C. §71", era: 2, detailKey: "1871_indian_appropriations_act" },
  { year: 1875, event: "Civil Rights Act of 1875 — Congress guarantees equal enjoyment of listed public accommodations and a federal remedy for racial denial of access. In 1883, the Civil Rights Cases will invalidate central provisions, documenting a legal rollback before Plessy. Source: 18 Stat. 335; U.S. Senate Historical Office", era: 2, detailKey: "1875_civil_rights_act" },
  { year: 1876, event: "United States v. Cruikshank — the Supreme Court narrowly construes federal enforcement in prosecutions arising from the Colfax Massacre, holding that the cited Fourteenth Amendment protections required state action and sharply weakening Reconstruction-era civil-rights enforcement. Source: 92 U.S. 542; Library of Congress; Federal Judicial Center", era: 2, detailKey: "1876_cruikshank" },
  { year: 1876, event: "United States v. Reese — the Supreme Court holds that the Fifteenth Amendment prohibits race-based denial or abridgment of voting rights but does not independently confer an affirmative right to vote. The distinction leaves room for later formal restrictions. Source: 92 U.S. 214; National Archives", era: 2, detailKey: "1876_reese" },
  { year: 1877, event: "Reconstruction ends — federal troops withdrawn from the South", era: 2 },
  { year: 1882, event: "Chinese Exclusion Act — first federal law to explicitly bar a racial group from immigration", era: 2 },
  { year: 1883, event: "Civil Rights Cases — the Supreme Court strikes down the Civil Rights Act of 1875, ruling that the 14th Amendment does not protect against private discrimination. The federal government cannot prohibit racial discrimination by private businesses. This ruling directly enables Jim Crow and dismantles every Reconstruction-era civil rights protection", era: 3 },
  { year: 1887, event: "Dawes Act — 90 million acres of Indigenous land stolen", era: 3 },
  { year: 1890, event: "Mississippi Constitution of 1890 — Article XII creates state voting and registration qualifications. The Mississippi Department of Archives and History identifies literacy tests and poll taxes as requirements that substantially excluded Black voters. The constitutional text establishes a state framework; local administration must be examined separately. Source: Mississippi Department of Archives and History", era: 3, detailKey: "1890_mississippi_constitution" },
  { year: 1890, event: "Wounded Knee Massacre — the U.S. Army's 7th Cavalry kills approximately 250–300 Lakota men, women, and children in South Dakota. The Army is attempting to disarm the Lakota, who are practicing the Ghost Dance — a spiritual movement the government perceives as a threat. Twenty soldiers receive the Medal of Honor. The massacre is the last major military action against Indigenous people", era: 3 },
  { year: 1896, event: "Plessy v. Ferguson — 'separate but equal' enshrined in law", era: 3 },
  { year: 1898, event: "Spanish-American War — Buffalo Soldiers fight for a country that returns them to Jim Crow", era: 3 },
  { year: 1898, event: "Wilmington Massacre — only successful coup d'état in U.S. history", era: 3 },
  { year: 1900, event: "North Carolina Suffrage Amendment — the state adds literacy and poll-tax requirements to voting while temporarily exempting those eligible before January 1, 1867 and their lineal descendants from the educational test if registered by 1908. The text establishes statewide qualifications; local administration requires separate evidence. Source: North Carolina Digital Collections", era: 3, detailKey: "1900_north_carolina_suffrage" },
  { year: 1901, event: "Alabama Constitution of 1901 — the state constitutional voting framework used literacy, employment, and property qualifications. The Alabama Department of Archives and History preserves the original 61-page document and identifies those restrictions. Source: Alabama Department of Archives and History", era: 3, detailKey: "1901_alabama_constitution" },
  { year: 1909, event: "NAACP founded by Du Bois, Wells, and others", era: 3 },
  { year: 1919, event: "Elaine Massacre — violence followed a September 30 meeting of Black sharecroppers’ Progressive Farmers and Household Union in Phillips County, Arkansas. The number of Black people killed remains unresolved; historical estimates vary substantially. Source: Federal Judicial Center; Encyclopedia of Arkansas", era: 3, detailKey: "1919_elaine_massacre" },
  { year: 1921, event: "1890 U.S. Census fire — a January 10 fire in the Commerce Department building damaged or destroyed most 1890 population schedules. Surviving fragments and special schedules remain, but the loss creates a documented genealogical gap. Source: U.S. Census Bureau; National Archives", era: 3, detailKey: "1921_1890_census_fire" },
  { year: 1921, event: "Tulsa Race Massacre — Greenwood District destroyed", era: 3 },
  { year: 1921, event: "Dyer Anti-Lynching Bill killed by Senate filibuster", era: 3 },
  { year: 1921, event: "Dyer Anti-Lynching Bill passes the House 230-119 — killed by Senate filibuster; federal government had the mechanism to stop lynching and chose not to use it", era: 3 },
  { year: 1923, event: "Moore v. Dempsey — the Supreme Court holds that a state murder trial hurried to conviction under mob domination, without due process, is void; where state corrective process is insufficient, a federal court must examine the alleged facts. Source: 261 U.S. 86; Federal Judicial Center", era: 3, detailKey: "1923_moore_dempsey" },
  { year: 1924, event: "Indian Citizenship Act — Native Americans are granted U.S. citizenship for the first time, 56 years after the 14th Amendment granted citizenship to formerly enslaved people. Several states continue to bar Native Americans from voting until 1948. The people whose land was taken are the last to be recognized as citizens of the country built on it", era: 3 },
  { year: 1924, event: "Virginia Racial Integrity Act — the Commonwealth creates a restrictive legal classification regime for marriage and vital records, later used in a wider administrative system that harmed Black and Indigenous Virginians. A state classification is not evidence of a person’s ancestry or sovereign citizenship. Source: Virginia Acts of Assembly; Library of Virginia", era: 3, detailKey: "1924_racial_integrity" },
  { year: 1930, event: "Census racial-classification instructions — enumerators were directed to return a person of mixed White and Negro ancestry as Negro regardless of percentage; a person of mixed Indian and Negro ancestry was generally to be returned as Negro unless Indian ancestry predominated and the person was generally accepted as Indian in the community. The instructions establish an administrative sorting rule, not individual ancestry or tribal citizenship. Source: U.S. Census Bureau", era: 3, detailKey: "1930_census_instructions" },
  { year: 1933, event: "1890 census disposal authorization — after limited salvage following the 1921 fire, Congress authorized disposal of the remaining unsalvageable 1890 schedules on February 21, 1933. The National Archives notes uncertainty about the final disposal date. Source: U.S. Census Bureau; National Archives Prologue", era: 3, detailKey: "1933_1890_census_disposal" },
  { year: 1934, event: "Indian Reorganization Act ends Dawes Act allotment", era: 3 },
  { year: 1935, event: "HOLC redlining maps — 'infiltration of Negro occupancy' explicitly listed as negative factor in neighborhood ratings", era: 3 },
  { year: 1942, event: "Bracero Program begins — 4.6 million Mexican workers exploited under conditions mirroring convict leasing", era: 3 },
  { year: 1944, event: "Smith v. Allwright — the Supreme Court strikes down Texas’s race-based Democratic primary, rejecting the claim that a party could use private status to evade constitutional voting protections. Source: 321 U.S. 649; NAACP Legal Defense Fund", era: 3, detailKey: "1944_smith_allwright" },
  { year: 1944, event: "GI Bill — racially administered, denying benefits to Black veterans", era: 3 },
  { year: 1954, event: "Brown v. Board of Education", era: 4 },
  { year: 1955, event: "Brown II — the Supreme Court orders states to begin public-school desegregation plans ‘with all deliberate speed.’ The phrase confirms an implementation duty but leaves substantial room for resistance and delay. Source: National Archives, Record Group 267", era: 4, detailKey: "1955_brown_ii" },
  { year: 1955, event: "Emmett Till murdered — Sheriff Strider suppresses evidence", era: 4 },
  { year: 1957, event: "Civil Rights Act of 1957 — Congress creates the Civil Rights Commission and Justice Department Civil Rights Division, and authorizes the Attorney General to seek injunctions against voting-rights obstruction by state officials. Source: Pub. L. 85-315, 71 Stat. 634; Constitution Annotated", era: 4, detailKey: "1957_civil_rights_act" },
  { year: 1960, event: "Civil Rights Act of 1960 — Congress expands federal voting-rights enforcement, including voter-registration record preservation and pattern-or-practice litigation. Source: Pub. L. 86-449, 74 Stat. 86; Constitution Annotated", era: 4, detailKey: "1960_civil_rights_act" },
  { year: 1963, event: "Birmingham campaign / Project C — in April and May, the SCLC and the Alabama Christian Movement for Human Rights directed a direct-action campaign from the A. G. Gaston Motel. Nationally circulated images documented police dogs and high-pressure hoses used against nonviolent protesters. Source: National Park Service; Library of Congress", era: 4, detailKey: "1963_birmingham_campaign" },
  { year: 1963, event: "Medgar Evers and the Jackson movement — the NAACP’s Mississippi field secretary organized voter-registration drives, boycotts, desegregation campaigns, and investigations of racial violence. He was killed at his Jackson home on June 12, 1963. Source: National Park Service; Library of Congress; National Archives", era: 4, detailKey: "1963_medgar_evers" },
  { year: 1964, event: "Twenty-fourth Amendment ratified — the Constitution prohibits poll taxes as a prerequisite to voting in federal elections. State-election poll taxes require separate litigation, resolved by Harper in 1966. Source: 78 Stat. 1117; U.S. House Office of the Historian", era: 4, detailKey: "1964_twenty_fourth_amendment" },
  { year: 1964, event: "Freedom Summer — COFO’s Mississippi voting-rights project brought together local Black organizers and roughly 1,000 out-of-state volunteers for voter-registration work, Freedom Schools, organizing, and the Mississippi Freedom Democratic Party. National Archives records document extensive arrests and violence. Source: National Archives", era: 4, detailKey: "1964_freedom_summer" },
  { year: 1964, event: "Civil Rights Act of 1964 — Congress prohibits discrimination in public accommodations and employment, expands school and public-facility desegregation tools, and creates the EEOC. Source: Pub. L. 88-352, 78 Stat. 241; National Archives", era: 4, detailKey: "1964_civil_rights_act" },
  { year: 1965, event: "Selma marches — the Dallas County Voters League, SNCC, SCLC, and local organizers led three Selma-to-Montgomery marches. The March 7 attack on marchers at the Edmund Pettus Bridge became known as Bloody Sunday. Source: National Archives", era: 4, detailKey: "1965_selma_marches" },
  { year: 1965, event: "Voting Rights Act passed", era: 4 },
  { year: 1965, event: "Moynihan Report blames Black family structure for poverty without acknowledging the documented policies (redlining, man-in-the-house rules) that caused it", era: 4 },
  { year: 1966, event: "Harper v. Virginia Board of Elections — the Supreme Court holds that a state cannot condition voting on payment of a fee or tax, ending state poll-tax barriers under the Fourteenth Amendment. Source: 383 U.S. 663; Library of Congress", era: 4, detailKey: "1966_harper" },
  { year: 1966, event: "South Carolina v. Katzenbach — the Supreme Court upholds the Voting Rights Act provisions before it as an appropriate exercise of Congress’s Fifteenth Amendment enforcement power, including affirmative remedies against voting discrimination. Source: 383 U.S. 301; Library of Congress; Constitution Annotated", era: 4, detailKey: "1966_katzenbach" },
  { year: 1966, event: "Project 100,000 — McNamara drafts 354,000 men deemed unfit for service; 40.6% are Black, assigned to combat at double the casualty rate", era: 4 },
  { year: 1967, event: "FBI COINTELPRO directive targets Black Nationalist organizations", era: 4 },
  { year: 1968, event: "Civil Rights Act of 1968 / Fair Housing Act — Title VIII prohibits discrimination in the sale or rental of housing and creates federal and private enforcement paths. The law targets a documented legal dimension of housing discrimination but does not erase prior redlining or guarantee equal housing access. Source: Pub. L. 90-284, 82 Stat. 73; U.S. House; U.S. Department of Justice", era: 4, detailKey: "1968_fair_housing" },
  { year: 1968, event: "American Indian Movement (AIM) founded in Minneapolis, Minnesota — by Dennis Banks, Clyde Bellecourt, and George Mitchell to address police brutality against urban Indigenous people and to assert treaty rights. The FBI immediately began surveilling it. By 1972, AIM led the Trail of Broken Treaties march to Washington D.C. By 1973, AIM occupied Wounded Knee for 71 days. The FBI maintained a 17,000-page file on AIM leader John Trudell. Source: American Indian Movement records; Church Committee Report (1976)", era: 4 },
  { year: 1968, event: "King v. Smith — Supreme Court strikes down 'man-in-the-house' rules that structurally excluded Black fathers from families", era: 4 },
  { year: 1968, event: "Kerner Commission Report — federal government concludes America is 'moving toward two societies, one Black, one white'; Johnson buries it", era: 4 },
  { year: 1969, event: "Allen v. State Board of Elections — the Supreme Court confirms a broad reading of Section 5 preclearance for covered changes in voting practices and procedures. Source: 393 U.S. 544; Library of Congress", era: 4, detailKey: "1969_allen" },
  { year: 1969, event: "Gaston County v. United States — the Supreme Court prevents a North Carolina county from reinstating a literacy test where the record of past educational discrimination against Black children made that test an unlawful voting barrier. Source: 395 U.S. 285; Library of Congress; Constitution Annotated", era: 4, detailKey: "1969_gaston_county" },
  { year: 1969, event: "Fred Hampton assassinated — FBI provides floor plan to Chicago police", era: 4 },
  { year: 1970, event: "Voting Rights Act Amendments of 1970 — Congress extends temporary Voting Rights Act provisions for five years. Source: Pub. L. 91-285, 84 Stat. 314; U.S. House Office of the Historian", era: 5, detailKey: "1970_vra_amendments" },
  { year: 1971, event: "Nixon's War on Drugs launched — Ehrlichman later admitted it was designed to target Black communities", era: 4 },
  { year: 1975, event: "Voting Rights Act Amendments of 1975 — Congress extends key provisions, permanently bans literacy tests, and requires bilingual election materials in qualifying language-minority jurisdictions. Source: Pub. L. 94-73, 89 Stat. 400; U.S. House Office of the Historian", era: 5, detailKey: "1975_vra_amendments" },
  { year: 1976, event: "Church Committee Report exposes COINTELPRO abuses", era: 5 },
  { year: 1980, event: "City of Rome v. United States — the Supreme Court upholds Congress’s authority to use the Voting Rights Act’s preclearance framework against covered electoral changes with discriminatory impact or effect. Source: 446 U.S. 156; Library of Congress; Constitution Annotated", era: 5, detailKey: "1980_city_of_rome" },
  { year: 1981, event: "First AIDS cases reported — Reagan administration does not publicly acknowledge for 6 years; 41,000 die", era: 5 },
  { year: 1982, event: "Voting Rights Act Amendments of 1982 — Congress extends key provisions for 25 years and continues language-minority protections; preclearance remains subject to its statutory coverage and exemption rules. Source: Pub. L. 97-205, 96 Stat. 131; U.S. House Office of the Historian", era: 5, detailKey: "1982_vra_amendments" },
  { year: 1986, event: "Anti-Drug Abuse Act — 100:1 crack/powder cocaine sentencing disparity; 78.7% of crack defendants were Black", era: 5 },
  { year: 1989, event: "Kerry Committee Report — U.S. Senate documents CIA awareness of Contra drug trafficking and deliberate inaction", era: 5 },
  { year: 1990, event: "NAGPRA passed — repatriation of Indigenous remains begins", era: 5 },
  { year: 1994, event: "Crime Bill — three strikes, mandatory minimums, truth-in-sentencing; 89% of federal capital prosecution defendants were Black or Hispanic", era: 5 },
  { year: 1998, event: "CIA Inspector General's Report confirms CIA failed to report Contra drug trafficking to law enforcement", era: 5 },
  { year: 2006, event: "Voting Rights Act Reauthorization — Congress extends specified Voting Rights Act and bilingual-election provisions for 25 years. In 2013, Shelby County will invalidate the coverage formula that activated preclearance. Source: Pub. L. 109-246, 120 Stat. 577; U.S. House Office of the Historian", era: 5, detailKey: "2006_vra_reauthorization" },
  { year: 2008, event: "Subprime mortgage crisis wipes out 53% of Black household wealth; DOJ later documents Wells Fargo targeted Black borrowers", era: 5 },
  { year: 2012, event: "Wells Fargo pays $175 million — largest fair lending settlement in DOJ history; loan officers documented calling Black borrowers 'mud people'", era: 5 },
  { year: 2013, event: "Shelby County v. Holder guts the Voting Rights Act", era: 5 },
  { year: 2020, event: "McGirt v. Oklahoma — Muscogee (Creek) reservation affirmed", era: 5 },
  { year: 2021, event: "George Floyd Justice in Policing Act passes the House — killed in the Senate; the Dyer Bill pattern repeats 100 years later", era: 5 },
  { year: 2022, event: "Emmett Till Antilynching Act — first federal anti-lynching law, 101 years late", era: 5 },
  { year: 2024, event: "CoreCivic and GEO Group generate $4.38 billion in revenue; their SEC filings document financial dependence on high incarceration rates", era: 5 },
  // BLACK NATIVE AMERICAN HISTORY — The Story This Encyclopedia Was Built to Tell
  // THE RENAMING CHAIN — documented in primary sources
  // PAPAL BULLS — The Legal Origin of Perpetual Slavery
  { year: 1452, event: "Dum Diversas — Pope Nicholas V issues the papal bull authorizing Portugal to 'invade, search out, capture, vanquish, and subdue all Saracens and pagans whatsoever... and reduce their persons to perpetual slavery.' This is the legal origin of race-based perpetual slavery — issued 40 years before Columbus reached the Americas. The word 'perpetual' means forever. Source: Pope Nicholas V, Dum Diversas (June 18, 1452), Doctrine of Discovery Project", era: 1 },
  { year: 1455, event: "Romanus Pontifex — Pope Nicholas V issues the second papal bull, extending perpetual slavery rights and first using the word 'negro' as a legal category: 'many Guineamen and other negroes, taken by force... have been sent to the said kingdoms.' This is the first documented use of 'negro' as a legal classification for enslaved people — 37 years before Columbus. The word was not a description. It was a legal instrument. Source: Pope Nicholas V, Romanus Pontifex (January 8, 1455), Papal Encyclicals Online", era: 1 },
  { year: 1493, event: "Inter Caetera — Pope Alexander VI extends the Doctrine of Discovery to the Americas, one year after Columbus's first voyage, granting Spain the right to 'subdue' the Indigenous peoples of the 'western and southern' lands. The same theological framework that authorized the enslavement of West Africans now authorizes the enslavement of the Taino, Arawak, Aztec, Maya, and every Indigenous nation of the Americas. Source: Pope Alexander VI, Inter Caetera (May 4, 1493), Doctrine of Discovery Project", era: 1 },
  { year: 1711, event: "Tuscarora War (1711–1715) — North Carolina colonists nearly destroy the Tuscarora Nation. Survivors are captured and sold into slavery under English names. The 1720s Carolina census records approximately 1,500 enslaved American Indians — appearing in colonial records not as Tuscarora, but under classical European slave names: Venus, Scipio, Caesar, Pompey. Their tribal identity is erased in the administrative record. Source: Bossy, Indian Slavery in Southeastern Indian and British Societies (2009), University of Nebraska Press", era: 1 },
  { year: 1719, event: "South Carolina colonial legislature passes a statute declaring: 'all such slaves as are not entirely Indian shall be accounted as negroe.' This single sentence legally transforms Indigenous identity into Black identity. A person who is half Yamasee and half African is no longer Yamasee — they are Negro. Their land claims, tribal affiliations, and sovereign status are erased by legislative decree. In Virginia, county records from 1691 to 1717 document the same process: 'Kate Indian' listed as 'negro slave' (1691 York County); 'Robin an Indian' reclassified as 'Robin a negro' (1715–1717). Source: Richard B. Moore, The Name Negro: Its Origin and Evil Use (1960), citing Colonial Records of South Carolina and Virginia County Records", era: 1 },
  { year: 1715, event: "Yamasee War — enslaved Africans and Indigenous people unite against colonial power in South Carolina. Enslaved Africans comprise 30% of the emergency colonial militia AND actively assist the Yamasee-Creek coalition. This is the earliest documented Black-Indigenous alliance in the American Southeast. Source: Fritz, Indians, Africans, and British Expansion in the Southeastern Borderlands (2014)", era: 1 },
  { year: 1835, event: "Second Seminole War begins — the most expensive Indian war in U.S. history ($20 million, 1,500 soldiers) was fought primarily to re-enslave Black Seminoles. John Horse (Juan Caballo) and Osceola led a Black-Seminole alliance against forced removal and re-enslavement. Joshua Giddings wrote: 'They had no alternative other than war or slavery; and they greatly preferred death upon the battle field, to chains and the scourge.' Source: Giddings, The Exiles of Florida (1858)", era: 2 },
  { year: 1866, event: "Treaty with the Cherokee — Article IX provides that specified Freedmen, free colored persons, and their descendants, subject to the article’s stated residence or return conditions, shall have all the rights of native Cherokees. The treaty text establishes its terms; individual descent and present citizenship require separate, person-specific and nation-governed analysis. Source: Treaty with the Cherokee (1866), Art. IX; 14 Stat. 799", era: 2, detailKey: "1866_cherokee_treaty" },
  { year: 1898, event: "Dawes Rolls enrollment begins — the Curtis Act of 1898 creates separate enrollment categories: 'Cherokee by blood,' 'intermarried whites,' and 'Freedmen.' Black Native Americans with Cherokee ancestry are enrolled as Freedmen rather than 'by blood,' denying them full tribal rights despite documented ancestral ties. By 1907, 4,924 Freedmen are enrolled. A 1872 petition from Cherokee Freedmen to President Grant documents: 'Some of us had fled North to get away from slavery... we were so far that we had no way of getting back.' Source: National Archives, Dawes Commission Records", era: 3 },
  { year: 1930, event: "1930 U.S. Census enumerator instructions direct that anyone with any 'Negro blood' be classified as 'Negro' — regardless of Indigenous ancestry, tribal affiliation, or self-identification. This administrative instruction completes a process that began with the 1719 South Carolina statute. An entire generation of Black Native Americans is reclassified into a single racial category that denies their Indigenous heritage. The National Archives holds both the 1719 statute and the 1930 Census enumerator manual. Source: Hendricks and Patterson, 'The 1930 Census in Perspective,' National Archives Prologue Magazine, Summer 2002", era: 4 },
  // ADDITIONAL GAP ENTRIES
  { year: 1865, event: "Freedmen’s Bureau established (March 3, 1865) — Congress creates a War Department bureau responsible for abandoned-land administration and matters involving refugees and freedpeople; its surviving Record Group 105 files document relief, labor, family, schooling, claims, land applications, and field-office work. Source: 13 Stat. 507–09; National Archives Record Group 105", era: 3, detailKey: "1865_freedmens_bureau" },
  { year: 1797, event: "Garifuna deportation — the British forcibly remove over 5,000 Garifuna people from St. Vincent to Roatan, Honduras. Those with more African features are specifically targeted for deportation — a racial selection process mirroring the 'one-drop rule' being applied simultaneously in North America. Only approximately 2,500 survive the journey. The Garifuna are the most complete documented parallel to the Black Native American story: a Black Indigenous people who survived colonial reclassification and maintained their identity. Source: Young, William. An Account of the Black Charaibs in the Island of St. Vincent's (1795)", era: 1 },
  { year: 1934, event: "Indian Reorganization Act (1934) — the first federal law to codify blood quantum as a legal standard for Indigenous identity, defining 'Indian' as including 'all other persons of one-half or more Indian blood.' No Indigenous nation used blood quantum before European contact. The system was designed to reduce the number of people who could claim Indigenous identity over time. Vine Deloria Jr. (Standing Rock Sioux) would later call it 'a slow-motion termination policy.' Source: Indian Reorganization Act (1934), 48 Stat. 984", era: 4 },
  { year: 1969, event: "Vine Deloria Jr. publishes 'Custer Died for Your Sins: An Indian Manifesto' — the foundational text of modern Indigenous rights scholarship. Deloria documents how blood quantum was invented by the U.S. government to reduce the number of people who could claim Indigenous identity, how the Dawes Rolls enrollment process erased Indigenous ancestry, and how the federal government's policies toward Indigenous peoples constitute a systematic program of cultural and legal termination. Source: Deloria, Vine Jr., Custer Died for Your Sins (1969), Macmillan", era: 5 },
  { year: 2001, event: "UNESCO proclaims the Language, Dance, and Music of the Garifuna as a 'Masterpiece of the Oral and Intangible Heritage of Humanity' — the highest international recognition of cultural heritage available. The Garifuna are descended from the Arawak and Carib nations of the Caribbean and escaped African enslaved people. The same colonial administration that tried to classify them as 'mere interlopers from Africa' in 1795 has been superseded by an international body that honors them. Source: UNESCO Intangible Cultural Heritage Designation (2001)", era: 5 },
  { year: 1960, event: "Richard B. Moore publishes 'The Name Negro: Its Origin and Evil Use' — documenting how 'Negro,' 'Black,' 'Colored,' and 'Indian' were administrative categories created by colonial administrators to replace tribal and ethnic identities. Moore documents the specific legal mechanisms: the 1719 South Carolina statute, the California Supreme Court's 1854 ruling that 'Black person' included all non-Caucasians, and the Virginia county records showing Indigenous people reclassified as Negro. 'Dogs and Slaves are Named by Their Masters; Free Men Name Themselves.' Source: Moore, Richard B., The Name Negro: Its Origin and Evil Use (1960), Black Classic Press", era: 5 },
  { year: 2007, event: "Cherokee Nation strips Freedmen descendants of citizenship in a special election, limiting tribal membership to those with 'Cherokee blood.' Approximately 2,800 descendants of the Cherokee Freedmen — people whose ancestors were guaranteed 'all the rights of native Cherokees' by the 1866 Treaty — lose their citizenship. This is the paper genocide of the Dawes Rolls playing out in the present day. Source: Cherokee Nation v. Nash, National Indian Law Library", era: 5 },
  { year: 2017, event: "U.S. District Court restores Cherokee Freedmen citizenship — ruling that the Cherokee Nation must honor the 1866 Treaty. The court states: 'The Cherokee Nation concedes that its power to determine tribal membership can be limited by treaty.' The 1866 Treaty is still legally binding. Black Native Americans whose identity was erased by the Dawes Rolls in 1898 have their rights restored 119 years later. Source: Cherokee Nation v. Nash (2017), U.S. District Court", era: 5 },
  { year: 1637, event: "Pequot War: captivity, enslavement, and Atlantic dispersal — after the 1637 conflict, Pequot women and children were divided among colonial and allied authorities; documentary evidence records captivity, forced labor, sale, and transfer to Caribbean and other English possessions. Source: Connecticut History / Mashantucket Pequot Museum & Research Center", era: 1, detailKey: "1637_pequot" },
  { year: 1662, event: "Virginia makes a child's status follow the mother — the Assembly enacts that children born in the colony are held bond or free according to their mother's condition, creating a legal mechanism for hereditary slavery. Source: Hening's Statutes at Large", era: 1, detailKey: "1662_maternal_status" },
  { year: 1701, event: "Carolina petition condemns 'Indian or Slave-Making' — political opponents accuse a former governor's network of turning the Indian trade into a system of captive-taking and warn that abuses against Indigenous nations invite war. Source: Narratives of Early Carolina, 1650–1708", era: 1, detailKey: "1701_carolina_petition" },
  { year: 1709, event: "John Lawson records Indigenous captives sold to the islands and refers to 'Indian Slaves in South-Carolina' — a colonial observer's direct account of the Indian slave trade and dispossession. Source: A New Voyage to Carolina", era: 1, detailKey: "1709_lawson" },
  { year: 1723, event: "Virginia's shared penal regime — an act governing 'Negros, Mulattos, and Indians, bond or free' restricts arms, movement, testimony, manumission, taxation, and voting, while preserving distinct exceptions. Source: Hening's Statutes at Large", era: 1, detailKey: "1723_classification" },
  { year: 1740, event: "South Carolina's multi-category slave code — the colony's law organizes people called Negro, Indian, mulatto, and mestizo inside one slave-property regime, with freedom requiring proof and only limited exceptions. Source: South Carolina statute of 1740", era: 1, detailKey: "1740_sc_code" },
  { year: 1795, event: "Treaty of San Lorenzo (27 October) — the United States and Spain open Mississippi navigation and New Orleans deposit rights, set a border, and undertake to restrain Indigenous diplomacy across their claimed territories. The treaty does not recognize a private Maison Rouge title. Source: Avalon Project treaty text", era: 1, detailKey: "1795_san_lorenzo" },
  { year: 1850, event: "United States v. Turner — the Supreme Court holds that the Carondelet–Maison Rouge instrument conveyed no private interest in land to Maison Rouge. This is the central legal record against the asserted private-title theory, while Washitaw land memory remains a documented community tradition. Source: 52 U.S. 663", era: 2, detailKey: "1850_turner" },
  { year: 1993, event: "Return of the Ancient Ones is published — Verdiacee 'Tiara' Washitaw-Turner Goston's community-authored text records Washitaw de Dugdahmoundyah history, Louisiana land memory, and Black Indigenous origin traditions. The publication is documented; its historical conclusions are presented as Tier 3 pending independent corroboration.", era: 5, detailKey: "1993_washitaw" },
  { year: 2019, event: "North American Aboriginal Society publishes a portrait and tribal-history compilation — a valuable community source index whose individual images, dates, and claims require independent verification before use as encyclopedia fact.", era: 5, detailKey: "2019_naas" },
  { year: 1661, event: "Barbados enacts a comprehensive slave code — a foundational legal regime in the English Atlantic. The surviving 1667 text reflects amendments, but it documents controls over movement, punishment, labor, and property status that informed later Caribbean and Carolina legal systems. Source: Barbados slave-code manuscript/transcription", era: 1, detailKey: "1661_barbados_code" },
  { year: 1690, event: "Carolina’s first comprehensive slave code — a mainland act shaped by earlier Caribbean codes. Its language explicitly governed Negro and Indian enslaved people while using White as the opposed category; the act was disallowed in 1691, though later Carolina laws borrowed heavily from its structure. Source: South Carolina Department of Archives and History, Act 57", era: 1, detailKey: "1690_carolina_code" },
  { year: 1783, event: "Treaty of Paris recognizes U.S. independence and asserts boundaries to the Mississippi — Britain and the United States set territorial boundaries without Indigenous nations as parties, creating a central interstate claim later contested across Indigenous homelands. Source: Treaty of Paris (3 September 1783), National Archives", era: 2, detailKey: "1783_paris_boundaries" },
  { year: 1865, event: "Sherman’s Special Field Orders No. 15 reserves specified coastal lands for settlement by formerly enslaved people — the order provided family plots of up to forty acres and possessory titles subject to later federal action. Source: Special Field Orders No. 15 (16 January 1865)", era: 2, detailKey: "1865_field_order" },
];
